def get_critical_points_from_parallelism(task_system_tau, sigma):
    critical_points = set()
    for task_i in task_system_tau.tasks:
        # For each task, consider its parallelism profile
        for lambda_j in task_i.lambda_points:
            # For each period multiple k
            # The paper states k in N (natural numbers, usually >=1 or >=0)
            # For practical bounds, k will be limited by P_tau or other bounds.
            # Here, we conceptually generate points.
            # For simplicity, let's assume a max_k for demonstration.
            max_k = 100 # Placeholder for actual bounds
            for k in range(max_k):
                point = k * task_i.T + lambda_j / sigma
                critical_points.add(point)
    return sorted(list(critical_points))
